import java.util.*;

public class Main {
    void hollowPyramid(int n) {
        for (int i = 1; i <= n; i++) {                // row i needs n - i spaces then a width 2i - 1 region
            int gap = n - i;
            int width = 2 * i - 1;
            for (int j = 0; j < gap + width; j++) {     // check every column this row actually uses
                if (j < gap) {
                    System.out.print(" ");                  // still inside the leading gap
                    continue;
                }
                int k = j - gap;                          // position inside the star region
                if (i == n) {
                    System.out.print("*");                  // the base row is completely solid
                } else if (k == 0 || k == width - 1) {
                    System.out.print("*");                  // left or right edge of this row
                } else {
                    System.out.print(" ");                  // interior of this row stays hollow
                }
            }
            System.out.println();                       // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.hollowPyramid(5);
    }
}

